-- Corrections du quiz de fin de semaine : activites_protection.
--
-- Générées par scripts/importer-quiz.mjs. `data` porte la version adulte, 
-- `data.version_enfant` la version enfant du même sujet. Remplace `version_moniteur`
-- (même rôle, jamais exploité par un vrai choix au lancement avant ce jour).

UPDATE game_cards SET related_objective_id = '75', data = '{"question":"Quelles sont les principales activités humaines sur le littoral ?","answers":["Uniquement la pêche professionnelle","Pêche, plaisance, sports nautiques, tourisme, transport maritime — nous partageons tous cet espace","Uniquement le tourisme et la baignade","Uniquement les activités industrielles"],"correctAnswerIndex":1,"explanation":"Le littoral est un espace partagé entre pêcheurs professionnels, plaisanciers, promeneurs, industries portuaires. Cette cohabitation nécessite des règles.","version_enfant":{"question":"Qui utilise la mer et la plage, en plus des vacanciers ?","answers":["Personne d''autre","Des pêcheurs, des ostréiculteurs, des sportifs, des bateaux de transport","Uniquement les surfeurs","Uniquement les scientifiques"],"correctAnswerIndex":1,"explanation":"La mer et la plage servent à beaucoup de monde en même temps : pêcheurs, ostréiculteurs, promeneurs, sportifs. C''est aussi un lieu de travail."}}'::jsonb WHERE id = 'b4c7330a-9953-422b-b313-eb0e836d7688';
UPDATE game_cards SET related_objective_id = '77', data = '{"question":"Qu''est-ce que l''économie bleue ?","answers":["L''économie des pays côtiers uniquement","Des activités économiques maritimes conçues pour rester rentables sans épuiser les ressources","La pêche industrielle intensive","Le tourisme balnéaire uniquement"],"correctAnswerIndex":1,"explanation":"L''économie bleue regroupe pêche, tourisme, énergies marines, transport, conçus pour durer sans dégrader les écosystèmes dont ils dépendent.","version_enfant":{"question":"C''est quoi, vivre de la mer sans l''épuiser ?","answers":["Pêcher le plus possible tant qu''il y a du poisson","Faire en sorte que ça marche encore dans cinquante ans","Arrêter complètement de pêcher","Ça n''existe pas"],"correctAnswerIndex":1,"explanation":"L''économie bleue, c''est vivre de la mer sans l''épuiser — pour que la pêche et le tourisme existent encore plus tard."}}'::jsonb WHERE id = '8e3f4173-65a9-49cc-9229-d0952de86a97';
UPDATE game_cards SET related_objective_id = '78', data = '{"question":"Comment les pratiques nautiques évoluent-elles vers plus de durabilité ?","answers":["Elles ne changent pas depuis 50 ans","Matériaux recyclés, mouillages sur bouées, chartes de bonnes pratiques : les choses évoluent","Uniquement par l''interdiction de certaines activités","Uniquement grâce à des réglementations obligatoires"],"correctAnswerIndex":1,"explanation":"Combinaisons en matériaux recyclés, mouillages qui épargnent les herbiers, chartes partagées entre clubs : le nautisme s''engage progressivement.","version_enfant":{"question":"Rien ne change dans la façon de naviguer, tout est comme avant ?","answers":["Oui, rien ne change jamais","Non, il y a déjà du matériel plus écologique et des zones mieux protégées","Si, mais seulement les bateaux à moteur","Non, tout empire"],"correctAnswerIndex":1,"explanation":"Les pratiques changent : matériaux recyclés, mouillages qui abîment moins le fond, zones protégées. Beaucoup a déjà changé."}}'::jsonb WHERE id = '2ece942a-af57-45ff-9738-08b176b6df86';
UPDATE game_cards SET related_objective_id = '126', data = '{"question":"Quelle différence y a-t-il entre sensibilisation et action environnementale ?","answers":["Ce sont deux mots pour la même chose","La sensibilisation c''est la prise de conscience, l''action c''est l''application concrète","La sensibilisation suffit, l''action n''est pas nécessaire","L''action est uniquement collective"],"correctAnswerIndex":1,"explanation":"Savoir que le plastique pollue (sensibilisation) et refuser une paille en plastique (action) sont deux étapes complémentaires mais distinctes.","version_enfant":{"question":"Savoir qu''un geste est important, ça suffit pour que ça change quelque chose ?","answers":["Oui, savoir suffit","Non, il faut aussi vraiment le faire","Non, il faut juste en parler","Oui, si beaucoup de gens le savent"],"correctAnswerIndex":1,"explanation":"Être sensibilisé, c''est comprendre. Agir, c''est changer quelque chose. Beaucoup savent ; peu changent leurs habitudes — c''est ce pas-là qui compte."}}'::jsonb WHERE id = '5fa9dd00-8a50-421c-8c40-e313e891f14a';
UPDATE game_cards SET related_objective_id = '81', data = '{"question":"Pourquoi chacun peut-il devenir acteur de la préservation de la biodiversité ?","answers":["Uniquement les scientifiques peuvent contribuer","Signaler une espèce, ramasser un déchet, respecter les zones : chaque geste compte pour la recherche","Uniquement en faisant des dons","C''est uniquement l''affaire des pouvoirs publics"],"correctAnswerIndex":1,"explanation":"Les sciences participatives collectent des millions d''observations citoyennes. Des milliers d''yeux valent mieux qu''un seul.","version_enfant":{"question":"Il faut être scientifique pour aider à protéger la nature ?","answers":["Oui, obligatoirement","Non, une simple observation peut déjà servir aux chercheurs","Non, il faut juste donner de l''argent","Non, ce n''est pas possible d''aider"],"correctAnswerIndex":1,"explanation":"Des milliers d''yeux valent mieux qu''un seul. Ce qu''on observe ici peut compléter ce que les scientifiques savent déjà."}}'::jsonb WHERE id = 'd01e19df-61f3-4c22-9f77-5b56c08f25f3';
UPDATE game_cards SET related_objective_id = '98', data = '{"question":"Pourquoi la protection de l''environnement est-elle aussi une question de santé humaine ?","answers":["Ce n''est pas lié — la santé humaine ne dépend pas de l''environnement marin","La pollution de l''eau et de l''air cause des maladies : ce qu''on rejette finit par nous revenir","Uniquement pour les personnes vivant près de la mer","Uniquement à cause des algues toxiques"],"correctAnswerIndex":1,"explanation":"Poissons contaminés, eau de baignade polluée, air chargé en particules : ce que l''on rejette dans l''eau ou dans l''air finit souvent par nous revenir.","version_enfant":{"question":"Ce qu''on jette dans l''eau, ça peut nous revenir ?","answers":["Non, jamais","Oui : dans l''eau de baignade, les coquillages, les poissons qu''on mange","Seulement si on habite tout près de la mer","Seulement pour les poissons, pas pour nous"],"correctAnswerIndex":1,"explanation":"Protéger l''environnement, c''est aussi se protéger soi-même : eau de baignade, coquillages, air — tout nous revient."}}'::jsonb WHERE id = '0dfb7b40-527c-4d2e-9a59-5cb3201b4e3a';
UPDATE game_cards SET related_objective_id = '111', data = '{"question":"Pourquoi le littoral normand est-il un territoire à forts enjeux de biodiversité ?","answers":["Uniquement parce qu''il est peu fréquenté","Il combine des milieux diversifiés (mer, estran, dunes, bocage) dans un équilibre fragile entre usages et nature","Parce que la Normandie interdit toute activité humaine sur son littoral","Uniquement parce que les eaux y sont très froides"],"correctAnswerIndex":1,"explanation":"La Normandie combine mer, littoral, plaine et bocage sur un territoire restreint — une diversité de milieux rare, mais fragile, prisée pour l''habitat, l''agriculture et le tourisme.","version_enfant":{"question":"Sur une même petite distance en Normandie, combien de paysages différents peut-on trouver ?","answers":["Un seul, toujours pareil","Plusieurs : la mer, la plage, la dune, la campagne","Seulement la mer et le sable","Ça n''a rien de spécial"],"correctAnswerIndex":1,"explanation":"La Normandie enchaîne mer, littoral, plaine et bocage sur peu de distance. Cette variété fait sa richesse — et sa fragilité."}}'::jsonb WHERE id = 'fda2bc17-8c13-43b2-a088-41c09b7b02a6';
UPDATE game_cards SET related_objective_id = '119', data = '{"question":"Quels sont les trois grands facteurs qui entraînent les courants marins de surface ?","answers":["La lune, le soleil et la pluie","Le vent, la rotation de la Terre (effet Coriolis) et la forme des côtes/fonds marins","La température, la salinité et les marées uniquement","La pression atmosphérique uniquement"],"correctAnswerIndex":1,"explanation":"Le vent pousse la surface de l''eau ; la rotation de la Terre dévie ensuite ce mouvement d''environ 45° dans l''hémisphère nord ; la géographie des côtes canalise le flux.","version_enfant":{"question":"Est-ce que le courant va toujours exactement dans le sens du vent ?","answers":["Oui, toujours pareil","Non, il part un peu de biais à cause de la rotation de la Terre","Non, il va toujours dans le sens contraire","Oui, sauf près des côtes"],"correctAnswerIndex":1,"explanation":"Le vent pousse l''eau, la rotation de la Terre la fait dévier, et la forme des côtes la canalise. Le courant ne suit jamais exactement le vent."}}'::jsonb WHERE id = '5a666861-6360-40f5-a4da-2a8ce9bfa625';
